<script setup lang="ts">
import { computed } from 'vue'
import type { RecordValue } from '@/api/workbench'
import { rows, record, text, texts, friendly, featureNames, number } from '@/services/presentation'
import { diagnosticReport, diagnosticTruthCounts, diagnosticGroupSummary, diagnosticGroupParticipation, diagnosticGroupNote } from '@/services/knowledge-diagnostics'
const props = defineProps<{ result:RecordValue; names:Map<string,string>; selectedCandidateId:string; graphId:string }>()
defineEmits<{ candidate:[id:string] }>()
const report = computed(() => diagnosticReport(props.result))
const usage = computed(() => record(report.value?.evidence_usage))
const groups = computed(() => rows(report.value?.equivalence_groups))
const facts = computed(() => diagnosticTruthCounts(report.value ?? {}))
const structural = computed(() => report.value?.grouping_basis === 'actual_structural_projection')
const featureLists = computed(() => [
  {key:'unreferenced_features',label:'未被逻辑条件引用',note:structural.value ? '这与是否进入结构评分是两件事；贡献观测可未被条件引用，但仍参与评分。' : '保留在 Evidence 中，但当前逻辑条件未引用。'},
  {key:'not_scored_features',label:'未进入本次评分的观测',note:'同一特征可能仅部分观测进入评分，数量按本次实际记录列出。'},
])
function name(id:unknown) {return props.names.get(text(id)) ?? friendly(id,'候选解释')}
</script>
<template>
  <section class="knowledge-diagnostics" aria-label="知识可分辨性与观测使用">
    <template v-if="report">
      <header><div><span class="section-kicker">KNOWLEDGE CHECK</span><h3>知识可分辨性与观测使用</h3><p>{{ diagnosticGroupSummary(report) }}</p></div><span class="tag">本次快照诊断</span></header>
      <div class="diagnostic-counts"><div><strong>{{ usage.total_observation_count }}</strong><span>保留观测 <small>其中 {{ usage.observed_observation_count }} 项已观测</small></span></div><div><strong>{{ usage.condition_grounded_observation_count }}</strong><span>{{ structural ? '作者条件绑定的观测' : '条件绑定的观测' }}<small>不等于成立或支持的数量</small></span></div><div><strong>{{ usage.score_input_status === 'available' ? usage.score_input_observation_count : '—' }}</strong><span>{{ structural ? '完整结构比较输入' : '本次评分输入' }}<small>{{ usage.score_input_status === 'not_ranked' ? '本次未启动候选排名' : usage.score_input_status === 'unavailable' ? '评分输入未生成' : '按实际观测计数' }}</small></span></div></div>
      <p class="diagnostic-check-note" v-if="facts.total">{{ structural ? '作者条件核对' : '条件事实核对' }}：{{ facts.total }} 项，{{ facts.satisfied }} 满足、{{ facts.unsatisfied }} 不满足<span v-if="facts.unknown">、{{ facts.unknown }} 缺测 / 未知</span>。{{ structural ? '这些逻辑条件核对不用于 RootKGD 的阈值或 AND/OR 评分。' : '不满足的事实同样被检查，可用于冲突与候选排除。' }}</p>
      <p v-if="structural" class="diagnostic-check-note">RootKGD 按图传播与本次完整贡献向量比较；传播覆盖范围不是评分向量的维数。它不执行条件阈值；新增 / 删除图关系可能改变结构评分。</p>
      <details v-if="groups.length" class="diagnostic-groups"><summary>查看 {{ groups.length }} 组相同签名的知识诊断</summary><article v-for="(group,index) in groups" :key="text(group.group_id)" :class="{ 'group-selected':texts(group.candidate_ids).includes(selectedCandidateId) }"><h4>第 {{ index+1 }} 组 · {{ structural ? '相同实际结构投影' : '相同期待条件' }}</h4><div class="group-members"><button v-for="(id,memberIndex) in texts(group.candidate_ids)" :key="id" type="button" :class="{active:id===selectedCandidateId}" @click="$emit('candidate',id)">{{ names.get(id) ?? friendly(texts(group.candidate_names)[memberIndex],'候选解释') }}</button></div><p>{{ diagnosticGroupNote(report,group) }}</p><p class="group-participation">本次排名资格：{{ diagnosticGroupParticipation(report,group).eligible }} 具备 / {{ diagnosticGroupParticipation(report,group).ineligible }} 不具备<span v-if="diagnosticGroupParticipation(report,group).unknown"> / {{ diagnosticGroupParticipation(report,group).unknown }} 未评估</span></p><ul v-if="rows(group.condition_signature).length"><li v-for="(condition,i) in rows(group.condition_signature)" :key="i">{{ friendly(condition.mode) }} · {{ name(condition.pattern_id) }}</li></ul><details v-if="rows(group.cost_priors).length" class="group-priors"><summary>假设成本与先验（不是观测区别）</summary><table><thead><tr><th>候选</th><th>成本 × 权重</th><th>计入代价</th></tr></thead><tbody><tr v-for="prior in rows(group.cost_priors)" :key="text(prior.candidate_id)"><td>{{ name(prior.candidate_id) }}</td><td>{{ number(prior.assumption_cost) }} × {{ number(prior.assumption_weight) }}</td><td>{{ prior.applied_to_score ? number(prior.weighted_cost) : '本次未计入' }}</td></tr></tbody></table></details></article><p class="diagnostic-check-note">可在图谱页检查 / 修改条件，或给当前候选添加有明确依据的专属条件。修改图谱只影响后续新分析，不改写本次结果。</p><router-link v-if="graphId && selectedCandidateId" class="text-button diagnostic-edit-link" :to="{name:'graphs',query:{graph:graphId,candidate:selectedCandidateId}}">在当前图谱检查此候选 →</router-link></details>
      <details class="diagnostic-usage"><summary>检查未引用与未评分的观测</summary><div v-for="list in featureLists" :key="list.key"><h4>{{ list.label }}</h4><p>{{ list.note }}</p><ul v-if="rows(usage[list.key]).length"><li v-for="feature in rows(usage[list.key])" :key="text(feature.feature_id)"><span>{{ featureNames[text(feature.feature_id)] ?? friendly(feature.feature_id) }}</span><strong>{{ feature.observation_count }} 项<small> / {{ feature.observed_count }} 已观测</small></strong></li></ul><p v-else>本次未列出此类观测。</p></div></details>
      <details v-if="texts(report.issues).length || report.grouping_status !== 'available'" class="diagnostic-issues"><summary>分组检查状态与限制</summary><p>{{ report.grouping_status === 'incomplete' ? '检查未完成，不能把缺少分组解释成已区分。' : '当前分组依据不足，不能把空分组解释成已区分。' }}</p><ul><li v-for="issue in texts(report.issues)" :key="issue">{{ issue }}</li></ul></details>
    </template>
    <p v-else class="diagnostics-not-generated"><strong>知识诊断：本次未生成</strong><span>此历史结果没有保存可分辨性与观测使用诊断，不使用当前图谱补算。</span></p>
  </section>
</template>
<style scoped>
.knowledge-diagnostics{margin:0 0 22px;padding:18px 20px;border:1px solid #dfe7f2;border-radius:8px;background:#fcfdff;color:#667a98;}.knowledge-diagnostics header{display:flex;align-items:center;gap:15px;justify-content:space-between;}.knowledge-diagnostics h3{font-size:14px;color:#415b80;margin:5px 0 7px;font-weight:550;}.knowledge-diagnostics h4{font-size:13px;margin:12px 0 8px;color:#516988;}.knowledge-diagnostics p{font-size:12px;line-height:1.8;margin:5px 0;}.section-kicker{font-size:10px;}.diagnostic-counts{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin:18px 0 12px;}.diagnostic-counts>div{display:flex;gap:10px;align-items:baseline;}.diagnostic-counts strong{font-size:23px;font-weight:500;color:#536d93;font-variant-numeric:tabular-nums;}.diagnostic-counts span{font-size:12px;line-height:1.7;}.diagnostic-counts small{display:block;font-size:11px;color:#8291a6;}.diagnostic-check-note{color:#7b8a9e;}.knowledge-diagnostics details{font-size:12px;line-height:1.8;}.knowledge-diagnostics>details{border-top:1px solid #e9edf5;margin-top:12px;padding-top:10px;}.knowledge-diagnostics summary{cursor:pointer;color:#617da4;}.diagnostic-groups article{border-left:2px solid #d9e2ef;margin:14px 0;padding:0 0 0 13px;}.diagnostic-groups article.group-selected{border-left-color:#87a4d1;}.group-members{display:flex;flex-wrap:wrap;gap:6px;}.group-members button{padding:5px 9px;border-radius:4px;border:1px solid #e1e7f0;background:white;color:#6c80a0;font-size:12px;text-align:left;}.group-members button.active{background:#edf3ff;border-color:#9cb6e1;color:#537bbd;}.diagnostic-groups ul{margin:8px 0;padding-left:18px;}.group-priors table{width:100%;border-collapse:collapse;margin-top:10px;font-size:12px;}.group-priors th,.group-priors td{text-align:left;padding:7px;border-bottom:1px solid #e7edf5;font-weight:400;}.group-priors th{color:#8797ac;}.diagnostic-usage>div{margin-top:12px;}.diagnostic-usage ul{padding:0;margin:8px 0;display:grid;grid-template-columns:1fr 1fr;gap:5px 22px;list-style:none;}.diagnostic-usage li{display:flex;gap:10px;justify-content:space-between;font-size:12px;}.diagnostic-usage strong{font-weight:450;white-space:nowrap;}.diagnostic-usage small{font-size:11px;color:#8b99ac;}.diagnostics-not-generated{display:flex;gap:14px;flex-wrap:wrap;margin:0!important;}.diagnostics-not-generated strong{font-weight:500;}.diagnostics-not-generated span{color:#8795a9;}@media(max-width:700px){.diagnostic-counts{grid-template-columns:1fr;gap:10px;}.knowledge-diagnostics header>.tag{display:none;}.diagnostic-usage ul{grid-template-columns:1fr;}}
</style>
